package com.maram.training.service.impl;
import com.maram.training.entity.Trainee; import com.maram.training.exception.*; import com.maram.training.repository.TraineeRepository; import com.maram.training.service.TraineeService; import org.springframework.data.domain.Sort; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional public class TraineeServiceImpl implements TraineeService{private final TraineeRepository r; public TraineeServiceImpl(TraineeRepository r){this.r=r;} public List<Trainee> all(String s,String d){return r.findAll(sort(s,d));} public List<Trainee> active(boolean a,String s,String d){return r.findByActive(a,sort(s,d));} public Trainee one(Long id){return r.findById(id).orElseThrow(()->new ResourceNotFoundException("Trainee not found: "+id));} public Trainee create(Trainee t){unique(t,null);t.setId(null);return r.save(t);} public Trainee replace(Long id,Trainee t){Trainee x=one(id);unique(t,x);x.setEmployeeNumber(t.getEmployeeNumber());x.setFullName(t.getFullName());x.setEmail(t.getEmail());x.setActive(t.isActive());return r.save(x);} public Trainee setActive(Long id,boolean a){Trainee x=one(id);x.setActive(a);return r.save(x);} public void delete(Long id){r.delete(one(id));}
 private void unique(Trainee c,Trainee e){if((e==null||!e.getEmployeeNumber().equalsIgnoreCase(c.getEmployeeNumber()))&&r.existsByEmployeeNumberIgnoreCase(c.getEmployeeNumber()))throw new BusinessRuleException("Employee number must be unique"); if((e==null||!e.getEmail().equalsIgnoreCase(c.getEmail()))&&r.existsByEmailIgnoreCase(c.getEmail()))throw new BusinessRuleException("Email must be unique");}
 private Sort sort(String s,String d){String f=Set.of("employeeNumber","email","active","fullName").contains(s)?s:"fullName";return Sort.by("desc".equalsIgnoreCase(d)?Sort.Direction.DESC:Sort.Direction.ASC,f);} }
